effect.shader:
void main() {
    vec4 camada = texture(inputImg, acScreenNorm);
    float a = camada.a;
    // Na MESMA precisão do AM: o `<shader>` dele não pede `precision`, e aí o AM compila com `precision mediump
    // float` (`ssl/BI`, `ShaderPrecision.MEDIUM`) — no celular, meia precisão. Variável por variável: um
    // `precision` global vazaria para os efeitos da cor junta. A GPU do PC ignora a precisão; o celular, não.
    mediump vec4 pre = vec4(camada.rgb * a, a);                  // o AM trabalha pré-multiplicado
    mediump vec4 cor1 = color1;
    mediump vec4 cor2 = color2;
    mediump float brilho = dot(pre.rgb, vec3(0.2126, 0.7152, 0.0722));
    // As cores do parâmetro entram RETAS, como no AM; a saída é pré-multiplicada (o buffer de 8 bits corta em 0 e 1).
    vec4 saida = clamp(mix(cor1, cor2, brilho) * pre.a, 0.0, 1.0);
    fragColor = saida.a > 0.0 ? vec4(min(saida.rgb / saida.a, vec3(1.0)), saida.a) : vec4(0.0);
}
